package com.example.g.security;import android.os.SystemClock;public final class EyeSession{public static final long DURATION_MS=30000;private static long unlockedAt;private EyeSession(){}public static boolean isUnlocked(){return unlockedAt>0&&SystemClock.elapsedRealtime()-unlockedAt<DURATION_MS;}public static void unlock(){unlockedAt=SystemClock.elapsedRealtime();}public static void lock(){unlockedAt=0;}public static long remaining(){return isUnlocked()?DURATION_MS-(SystemClock.elapsedRealtime()-unlockedAt):0;}}
